package com.wefyx.support.notification;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/notifications") public class AccountNotificationController{private final AccountNotificationRepository repository;public AccountNotificationController(AccountNotificationRepository r){repository=r;}@GetMapping public List<AccountNotification> mine(Authentication auth){return repository.findByRecipientEmailIgnoreCaseOrderByCreatedAtDesc(auth.getName());}@PatchMapping("/{id}/read")public AccountNotification read(@PathVariable Long id,Authentication auth){var n=repository.findById(id).orElseThrow();if(!n.getRecipientEmail().equalsIgnoreCase(auth.getName()))throw new org.springframework.security.access.AccessDeniedException("Not your notification");n.setRead(true);return repository.save(n);}}
